const BUILD_HASH = '1c9ac00';
const CACHE_PREFIX = 'yinyun-admin-';
const PRECACHE_NAME = `${CACHE_PREFIX}${BUILD_HASH}-precache`;
const RUNTIME_CACHE_NAME = `${CACHE_PREFIX}${BUILD_HASH}-runtime`;
const CONFIG_PATH = '/js/config.js';
const CONFIG_CACHE_KEY = `${CONFIG_PATH}?__pwa_lkg=${BUILD_HASH}`;

// PRECACHE:START - generated by scripts/generate-pwa-precache.mjs
const PRECACHE_URLS = [
    "./",
    "./index.html",
    "./app.js",
    "./icon.svg",
    "./js/library-integration.js",
    "./js/notification-engine.js",
    "./js/ui-utils.js",
    "./manifest.json",
    "./style.css",
    "./tailwind.generated.css",
    "./vendor/fonts/inter-1.woff2",
    "./vendor/fonts/inter-2.woff2",
    "./vendor/fonts/inter-3.woff2",
    "./vendor/fonts/inter-4.woff2",
    "./vendor/fonts/inter-5.woff2",
    "./vendor/fonts/inter-6.woff2",
    "./vendor/fonts/inter-7.woff2",
    "./vendor/fonts/inter.css",
    "./vendor/js/marked.min.js",
    "/_player/assets/fontawesome/css/all.min.css",
    "/_player/assets/fontawesome/webfonts/fa-brands-400.woff2",
    "/_player/assets/fontawesome/webfonts/fa-regular-400.woff2",
    "/_player/assets/fontawesome/webfonts/fa-solid-900.woff2",
    "/_player/assets/icons/icon-180.png",
    "/_player/assets/icons/icon-192.png",
    "/_player/assets/icons/icon-512.png",
    "/_player/assets/icons/icon-maskable-512.png",
    "/_player/assets/logo.svg",
];
// PRECACHE:END

const PRECACHE_URLS_ABSOLUTE = new Set(PRECACHE_URLS.map(url => new URL(url, self.registration.scope).href));
const isCacheableResponse = (response) => Boolean(
    response && response.ok && (response.type === 'basic' || response.type === 'cors')
);
const isHashedAsset = (pathname) => /(?:^|[._-])[a-f0-9]{8,}(?:[._-]|\.)/i.test(pathname.split('/').pop() || '');

const shouldBypass = (request, url) => {
    if (request.method !== 'GET' || url.origin !== self.location.origin) return true;
    if (request.headers.has('range')) return true;
    if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/rest/')) return true;
    if (/\.(mp3|flac|m4a|ogg|aac|wav|opus|mp4|webm)(?:$|\/)/i.test(url.pathname)) return true;
    if (url.pathname === CONFIG_PATH) return false;
    const scopePath = new URL(self.registration.scope).pathname;
    return !(url.pathname.startsWith(scopePath) || url.pathname.startsWith('/_player/assets/'));
};

const putIfCacheable = async (cacheName, request, response) => {
    if (!isCacheableResponse(response)) return response;
    const cache = await caches.open(cacheName);
    await cache.put(request, response.clone());
    return response;
};

const networkFirstNavigation = async (request) => {
    const runtime = await caches.open(RUNTIME_CACHE_NAME);
    const precache = await caches.open(PRECACHE_NAME);
    try {
        return await putIfCacheable(RUNTIME_CACHE_NAME, request, await fetch(request, { cache: 'no-store' }));
    } catch {
        return (await runtime.match(request, { ignoreSearch: true })) ||
            (await precache.match(request, { ignoreSearch: true })) ||
            (await precache.match(new URL('./', self.registration.scope).href, { ignoreSearch: true })) ||
            Response.error();
    }
};

const networkFirstConfig = async () => {
    const cache = await caches.open(RUNTIME_CACHE_NAME);
    try {
        const response = await fetch(CONFIG_PATH, { cache: 'no-store', credentials: 'same-origin' });
        if (isCacheableResponse(response)) await cache.put(CONFIG_CACHE_KEY, response.clone());
        return response;
    } catch {
        return (await cache.match(CONFIG_CACHE_KEY)) || Response.error();
    }
};

const networkFirstAsset = async (request) => {
    const runtime = await caches.open(RUNTIME_CACHE_NAME);
    const precache = await caches.open(PRECACHE_NAME);
    try {
        return await putIfCacheable(RUNTIME_CACHE_NAME, request, await fetch(request, { cache: 'no-store' }));
    } catch {
        return (await runtime.match(request, { ignoreSearch: true })) ||
            (await precache.match(request.url, { ignoreSearch: true })) ||
            Response.error();
    }
};

const cacheFirstHashedAsset = async (request) => {
    const runtime = await caches.open(RUNTIME_CACHE_NAME);
    const precache = await caches.open(PRECACHE_NAME);
    const cached = (await runtime.match(request, { ignoreSearch: true })) ||
        (await precache.match(request.url, { ignoreSearch: true }));
    if (cached) return cached;
    return putIfCacheable(RUNTIME_CACHE_NAME, request, await fetch(request));
};

self.addEventListener('install', (event) => {
    event.waitUntil((async () => {
        const cache = await caches.open(PRECACHE_NAME);
        await Promise.all(PRECACHE_URLS.map(async (url) => {
            const absoluteUrl = new URL(url, self.registration.scope).href;
            const fetchUrl = new URL(absoluteUrl);
            fetchUrl.searchParams.set('__pwa', BUILD_HASH);
            const request = new Request(fetchUrl.href, { cache: 'reload', credentials: 'same-origin' });
            const response = await fetch(request);
            if (!isCacheableResponse(response)) throw new Error(`[Admin SW] Precache failed for ${absoluteUrl}: HTTP ${response.status}`);
            await cache.put(absoluteUrl, response);
        }));
    })());
});

self.addEventListener('fetch', (event) => {
    const url = new URL(event.request.url);
    if (shouldBypass(event.request, url)) return;
    if (url.pathname === CONFIG_PATH) {
        event.respondWith(networkFirstConfig());
        return;
    }
    if (event.request.mode === 'navigate') {
        event.respondWith(networkFirstNavigation(event.request));
        return;
    }
    event.respondWith(isHashedAsset(url.pathname)
        ? cacheFirstHashedAsset(event.request)
        : networkFirstAsset(event.request));
});

self.addEventListener('activate', (event) => {
    event.waitUntil((async () => {
        const cacheNames = await caches.keys();
        await Promise.all(cacheNames.map((cacheName) => {
            if (cacheName.startsWith(CACHE_PREFIX) && cacheName !== PRECACHE_NAME && cacheName !== RUNTIME_CACHE_NAME) {
                return caches.delete(cacheName);
            }
            return undefined;
        }));
        await self.clients.claim();
    })());
});

self.addEventListener('message', (event) => {
    if (event.data?.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});
